WITH rollup_totals AS (SELECT o.channel, s.method, COUNT(*) AS num_rows, ROUND(AVG(s.amount), 2) AS avg_amount FROM payments s JOIN orders o ON s.order_id = o.id GROUP BY ROLLUP (o.channel, s.method)) SELECT channel, method, num_rows, CASE WHEN channel RLIKE '^(store|partner)$' THEN 'EXTENDED' WHEN channel RLIKE '^(web|mobile)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS channel_zone FROM rollup_totals ORDER BY method
